using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckGiantSwing.Editor {
public static class SwingAuthoring {
 public const string Folder="TruckGiantSwing",Scene="Assets/TruckGiantSwing/Scenes/TruckGiantSwing.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<SwingMatch>(Folder);m.setup.count=2;m.NormalizeSetup();m.feedback.clips=LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create();var grass=SportsEventAuthoring.Mat(Folder,"Mown landing meadow",new Color(.3f,.46f,.2f),.1f);grass.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NWH/Common/Textures/Ground/GrassAlbedo.png");grass.mainTextureScale=new Vector2(40,70);var ground=SportsEventAuthoring.Box("Physical continuous landing meadow",new Vector3(0,-.5f,67),new Vector3(240,1,250),grass,SportsEventAuthoring.Contact(Folder,"Meadow contact",.55f,.18f));ground.AddComponent<SwingGround>();var steel=SportsEventAuthoring.Mat(Folder,"Galvanised swing steel",new Color(.25f,.32f,.36f),.75f);steel.SetFloat("_Metallic",.7f);var brass=SportsEventAuthoring.Mat(Folder,"Safety yellow joints",new Color(.95f,.63f,.12f),.48f);var cable=SportsEventAuthoring.Mat(Folder,"Braided cable",new Color(.16f,.18f,.2f),.62f);cable.SetFloat("_Metallic",.8f);var frame=new GameObject("Purpose-built bolted giant swing gantry").transform;
 for(int x=-1;x<=1;x+=2){for(int z=-1;z<=1;z+=2){Beam("Gantry tubular leg",new Vector3(x*6,.15f,z*9),new Vector3(x*4.2f,26,0),.3f,steel,frame,true);var foot=SportsEventAuthoring.Box("Bolted concrete foot",new Vector3(x*6,.12f,z*9),new Vector3(1.7f,.24f,1.7f),brass,null,frame);for(int bolt=0;bolt<4;bolt++)Beam("Anchor bolt",new Vector3(x*6+(bolt%2==0?-.5f:.5f),.25f,z*9+(bolt<2?-.5f:.5f)),new Vector3(x*6+(bolt%2==0?-.5f:.5f),.4f,z*9+(bolt<2?-.5f:.5f)),.075f,steel,frame,false);}Beam("A-frame cross brace",new Vector3(x*5.1f,12,-4.5f),new Vector3(x*5.1f,12,4.5f),.16f,brass,frame,false);}
 Beam("Axle crossbeam",new Vector3(-5,25,0),new Vector3(5,25,0),.5f,steel,frame,true);m.pivot=new GameObject("Fixed physical hinge pivot").transform;m.pivot.position=new Vector3(0,24,0);for(int x=-1;x<=1;x+=2)Beam("Yellow axle bearing",new Vector3(x*1.7f-.3f,24,0),new Vector3(x*1.7f+.3f,24,0),.4f,brass,frame,false);
 var seat=new GameObject("Real hinged load cradle");seat.transform.position=new Vector3(0,4,0);m.seat=seat.AddComponent<Rigidbody>();m.seat.mass=3;m.seat.isKinematic=true;m.seat.interpolation=RigidbodyInterpolation.Interpolate;m.seat.solverIterations=20;m.seat.solverVelocityIterations=12;m.seat.angularDamping=.025f;m.seat.linearDamping=.008f;m.seat.maxAngularVelocity=1.35f;var support=seat.AddComponent<BoxCollider>();support.size=new Vector3(3.8f,.3f,5);support.sharedMaterial=SportsEventAuthoring.Contact(Folder,"Cradle contact",.65f,.05f);m.rigVisual=new GameObject("Cradle and moving cable render rig").transform;m.rigVisual.SetParent(seat.transform,false);SportsRallyAuthoring.Prop(m.rigVisual,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Pallet Variant.prefab",Vector3.zero,new Vector3(3.7f,.3f,4.9f));for(int side=-1;side<=1;side+=2)Beam("Cradle polished edge",new Vector3(side*1.9f,4.25f,-2.5f),new Vector3(side*1.9f,4.25f,2.5f),.12f,steel,m.rigVisual,false);m.cables=new Transform[2];for(int i=0;i<2;i++)m.cables[i]=Beam("Braided suspension cable "+i,new Vector3(i==0?-1.7f:1.7f,4,0),new Vector3(i==0?-1.7f:1.7f,24,0),.075f,cable,m.rigVisual,false).transform;
 m.truck=SportsEventAuthoring.Truck(m,Folder,"The swinging truck",new Vector3(-10,1.5f,0),0);SportsRallyAuthoring.FitTruck(m.truck);m.truck.gameObject.AddComponent<SwingLanding>().match=m;m.truck.body.angularDamping=.08f;m.truck.body.maxAngularVelocity=5;m.cameraRig=SportsEventAuthoring.Camera("Stable swing broadcast and flight camera");m.cameraRig.view.farClipPlane=600;m.cameraRig.Pose(new Vector3(0,14,3),new Vector3(32,8,-26),60,true);SportsRallyAuthoring.TuneCamera(m.cameraRig);m.cameras=new[]{m.cameraRig.view};m.replay=SportsRallyAuthoring.Replay(m,new[]{m.truck.visuals,m.rigVisual});m.replay.capacity=1200;m.replay.interval=.05f;
 Target("TEN",new Vector3(0,.018f,29),new Vector2(28,14),10,new Color(.15f,.6f,.9f),false);Target("TWENTY FIVE",new Vector3(-5,.024f,46),new Vector2(12,12),25,new Color(.95f,.55f,.12f),true);Target("FIFTY",new Vector3(6,.03f,58),new Vector2(12,14),50,new Color(.65f,.27f,.85f),false);Target("BULLSEYE",new Vector3(3,.035f,51),new Vector2(4.6f,4.6f),100,new Color(.95f,.2f,.26f),true);for(int i=0;i<31;i++){float z=18+i*3;SportsRallyAuthoring.Prop(frame,"Assets/RoadPropsPack/URP/Prefabs/RoadBlock02_URP.prefab",new Vector3(-22,0,z),new Vector3(2,.7f,.4f));}for(int i=0;i<25;i++)LWS.TruckBaseJumping.Editor.BaseSkyAuthoring.Scenery(frame,new Vector3(i%2==0?-52:52,0,20+i*5),7,i%4!=0,Folder);SportsRallyAuthoring.Prop(frame,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_CableReel01 Variant.prefab",new Vector3(-11,0,-7),new Vector3(3.5f,3,3.5f));var sign=SportsEventAuthoring.Label("Gantry title","GIANT SWING\nPUMP · RELEASE · FLY",new Vector3(0,26.5f,0),.24f,Color.white);sign.transform.rotation=Quaternion.identity;SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);SportsEventAuthoring.Save(Folder);Validate();}
 static GameObject Beam(string name,Vector3 a,Vector3 b,float radius,Material mat,Transform parent,bool collide){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(parent,true);g.transform.position=(a+b)*.5f;g.transform.rotation=Quaternion.FromToRotation(Vector3.up,(b-a).normalized);g.transform.localScale=new Vector3(radius*2,(b-a).magnitude*.5f,radius*2);g.GetComponent<Renderer>().sharedMaterial=mat;if(!collide)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static void Target(string name,Vector3 p,Vector2 size,int score,Color color,bool round){var mat=SportsEventAuthoring.Mat(Folder,name+" landing inlay",color,.25f);GameObject g;if(round){g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.transform.position=p;g.transform.localScale=new Vector3(size.x,.015f,size.y);UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=mat;}else g=SportsEventAuthoring.Box(name,p,new Vector3(size.x,.03f,size.y),mat);g.name="Painted target "+score;var label=SportsEventAuthoring.Label(name+" score",score.ToString(),p+Vector3.up*.055f,score==100?.45f:1,Color.white);label.transform.rotation=Quaternion.Euler(90,0,0);}
 public static void Validate(){EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<SwingMatch>();if(m==null||m.truck==null||m.seat==null||m.pivot==null||m.replay.sources.Length!=2||m.cables.Length!=2)throw new Exception("Swing authoring references missing");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Swing requires one listener");Debug.Log("SWING_SAVED_VALIDATED real pendulum and render-only replay");}
}
}
